def forwards_copy_links_and_statuses(apps, schema_editor):
    PurchaseOrder = apps.get_model("purchase", "PurchaseOrder")
    PurchaseRequisitionItem = apps.get_model("purchase", "PurchaseRequisitionItem")
    PurchaseReturn = apps.get_model("purchase", "PurchaseReturn")
    DebitNote = apps.get_model("purchase", "DebitNote")

    # PO header PR -> per-line PR item: match each PO line to the source
    # PR's line for the same item.
    for po in PurchaseOrder.objects.exclude(purchase_requisition=None):
        pr_items = {i.item_id: i for i in PurchaseRequisitionItem.objects.filter(purchase_requisition_id=po.purchase_requisition_id)}
        for line in po.items.all():
            pr_item = pr_items.get(line.item_id)
            if pr_item is not None:
                line.pr_item = pr_item
                line.save(update_fields=["pr_item"])

    # Debit Note: Return link -> that Return's Purchase Invoice.
    for dn in DebitNote.objects.exclude(purchase_return=None).select_related("purchase_return"):
        dn.purchase_invoice_id = dn.purchase_return.purchase_invoice_id
        dn.save(update_fields=["purchase_invoice"])

    # Approval statuses -> refund statuses. Nothing has been refunded yet,
    # so everything starts Unpaid; a Rejected Debit Note becomes Cancelled.
    PurchaseReturn.objects.update(status="Unpaid")
    DebitNote.objects.filter(status="Rejected").update(status="Cancelled")
    DebitNote.objects.exclude(status="Cancelled").update(status="Unpaid")


